data.query:
query Initiatives($after: String, $first: Int) {
    initiatives(after: $after, first: $first) {
        nodes {
            id
            name
            description
            status
            createdAt
            updatedAt
            projects {
                nodes {
                    id
                    name
                }
            }
        }
        pageInfo {
            hasNextPage
            endCursor
        }
    }
}
